<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:'{{ $fontFamily }}';font-size:8pt}h1,h2,.bold,th,tfoot td{font-weight:bold}h1{text-align:center;font-size:14pt;margin:0} .meta{text-align:center;margin:2mm 0 5mm}table{width:100%;border-collapse:collapse;margin-bottom:5mm}th,td{border:.2mm solid #777;padding:1.2mm;vertical-align:top}th{text-align:center}.num{text-align:center}.grade{font-size:10pt;margin:3mm 0 1.5mm}</style></head><body><h1>{{ $examName }}</h1><div class="meta"><b>Finalized Non-Cadre Circular — Version {{ $version->version }}</b><br>Generated: {{ $generatedAt->format('d-m-Y h:i:s A') }}</div>@foreach($groups as $grade=>$posts)<div class="grade"><b>Grade: {{ $grade }}</b></div><table><thead><tr><th>Grade</th><th>Serial</th><th>Sub Serial</th><th>Ministry / Entity</th><th>Post</th><th>Post Code</th><th>Post Count</th><th>Bachelor Subjects</th><th>Special Requirement</th></tr></thead><tbody>@foreach($posts as $p)<tr><td class="num">{{ $p->post_grade ?? '—' }}</td><td class="num">{{ $p->post_serial }}</td><td class="num">{{ $p->post_sub_serial ?? '—' }}</td><td>{{ $p->ministry }}@if($p->entity)<br>{{ $p->entity }}@endif</td><td>{{ $p->post_title }}@if($p->post_title_bn)<br>{{ $p->post_title_bn }}@endif</td><td class="num"><b>{{ $p->post_code }}</b></td><td class="num">{{ $p->post_count }}</td><td>{{ $p->bachelor_subject_codes ? str_replace('|', ', ', $p->bachelor_subject_codes) : 'ALL' }}</td><td>{{ $p->special_requirement ? 'REVIEW REQUIRED — '.$p->special_requirement_note : '—' }}</td></tr>@endforeach</tbody><tfoot><tr><td colspan="6">TOTAL POST COUNT</td><td class="num">{{ $posts->sum('post_count') }}</td><td colspan="2"></td></tr></tfoot></table>@endforeach</body></html>